// AgentServiceHandler is an implementation of the agentfleet.v1.AgentService service.
type AgentServiceHandler interface {
	ListDefinitions(context.Context, *connect.Request[v1.AgentServiceListDefinitionsRequest]) (*connect.Response[v1.AgentServiceListDefinitionsResponse], error)
	// Threads (docs/adr/0067): a thread is one definition session.
	ListThreads(context.Context, *connect.Request[v1.ListThreadsRequest]) (*connect.Response[v1.ListThreadsResponse], error)
	CreateThread(context.Context, *connect.Request[v1.CreateThreadRequest]) (*connect.Response[v1.CreateThreadResponse], error)
	PostMessage(context.Context, *connect.Request[v1.AgentServicePostMessageRequest]) (*connect.Response[v1.AgentServicePostMessageResponse], error)
	GetTranscript(context.Context, *connect.Request[v1.AgentServiceGetTranscriptRequest]) (*connect.Response[v1.AgentServiceGetTranscriptResponse], error)
	StreamTranscript(context.Context, *connect.Request[v1.AgentServiceStreamTranscriptRequest], *connect.ServerStream[v1.AgentServiceStreamTranscriptResponse]) error
	// Decisions: each names the seq of an unanswered request of its type. Each is AnswerDecision for that request.
	RespondToPermission(context.Context, *connect.Request[v1.AgentServiceRespondToPermissionRequest]) (*connect.Response[v1.AgentServiceRespondToPermissionResponse], error)
	AnswerQuestion(context.Context, *connect.Request[v1.AgentServiceAnswerQuestionRequest]) (*connect.Response[v1.AgentServiceAnswerQuestionResponse], error)
	ApprovePlan(context.Context, *connect.Request[v1.ApprovePlanRequest]) (*connect.Response[v1.ApprovePlanResponse], error)
	// The decision deck (docs/adr/0082 §5), whatever the kind: an admin in the console sees the decisions of every
	// session that is not archived, console and repo sessions included; anyone else, those on the threads they may read.
	ListDecisions(context.Context, *connect.Request[v1.ListDecisionsRequest]) (*connect.Response[v1.ListDecisionsResponse], error)
	GetDecision(context.Context, *connect.Request[v1.GetDecisionRequest]) (*connect.Response[v1.GetDecisionResponse], error)
	// Answers one open decision by id. An admin in the console answers any decision it can see; anyone else, on the
	// threads canAnswer allows (docs/adr/0067 §2).
	AnswerDecision(context.Context, *connect.Request[v1.AnswerDecisionRequest]) (*connect.Response[v1.AnswerDecisionResponse], error)
	// Sends the decisions version, then each change: the version reached and the ids that changed. It ends after 90 s;
	// the client reconnects with since_version and re-reads the ids it holds.
	WatchDecisions(context.Context, *connect.Request[v1.WatchDecisionsRequest], *connect.ServerStream[v1.WatchDecisionsResponse]) error
	// Control: the owner's or an admin's.
	SetConfig(context.Context, *connect.Request[v1.SetConfigRequest]) (*connect.Response[v1.SetConfigResponse], error)
	Stop(context.Context, *connect.Request[v1.StopRequest]) (*connect.Response[v1.StopResponse], error)
	GetStatus(context.Context, *connect.Request[v1.GetStatusRequest]) (*connect.Response[v1.GetStatusResponse], error)
	// Clients only (docs/adr/0066 §6-7, 0070).
	Open(context.Context, *connect.Request[v1.OpenRequest]) (*connect.Response[v1.OpenResponse], error)
	CloseThread(context.Context, *connect.Request[v1.CloseThreadRequest]) (*connect.Response[v1.CloseThreadResponse], error)
	Invoke(context.Context, *connect.Request[v1.InvokeRequest]) (*connect.Response[v1.InvokeResponse], error)
	// CoreService.WaitForSpawn shares the response.
	// buf:lint:ignore RPC_REQUEST_RESPONSE_UNIQUE
	WaitForResult(context.Context, *connect.Request[v1.WaitForResultRequest]) (*connect.Response[v1.WaitForResultResponse], error)
	// docs/adr/0084 §7: the owner talks to a standing character from the game, straight from the browser. An admin, from
	// the console or an admin origin; the message is the owner's own (T0).
	PostToCharacter(context.Context, *connect.Request[v1.PostToCharacterRequest]) (*connect.Response[v1.PostToCharacterResponse], error)
	// docs/adr/0084 §7: the lines characters speak (CoreService.Speak) to the owner's browser, live only: nothing is
	// stored, and a line spoken while nobody watches is dropped. An admin, from the console or an admin origin.
	WatchSpeech(context.Context, *connect.Request[v1.WatchSpeechRequest], *connect.ServerStream[v1.WatchSpeechResponse]) error
	// docs/adr/0084 amendment A3: every character, started or not, for the game. The owner only (an admin, from the
	// console or an admin origin).
	ListCharacters(context.Context, *connect.Request[v1.ListCharactersRequest]) (*connect.Response[v1.ListCharactersResponse], error)
	// Sends every character, then each character that changed (whole, never a diff). It ends after 90 s; the client
	// reconnects and gets the baseline again.
	WatchCharacters(context.Context, *connect.Request[v1.WatchCharactersRequest], *connect.ServerStream[v1.WatchCharactersResponse]) error
	// docs/adr/0084 amendment A4, owner only. Start makes the character's session, or resumes a stopped one with every
	// thread's SDK session id and cursor kept; it returns the new state at once and warms nothing (the first message does).
	// Starting a started character returns its state; on a character still stopping, state "stopping" with why "pod drain".
	StartCharacter(context.Context, *connect.Request[v1.StartCharacterRequest]) (*connect.Response[v1.StartCharacterResponse], error)
	// Stops the pod and keeps every thread's SDK session id and cursor; only a turn in flight is aborted, like Ctrl-C. No
	// confirm: Start resumes it. Stopping a stopped character returns its state.
	StopCharacter(context.Context, *connect.Request[v1.StopCharacterRequest]) (*connect.Response[v1.StopCharacterResponse], error)
	// docs/adr/0084 amendment A5, owner only: one thread's transcript in full, as the console shows it, tool results
	// included. The character's standing session is owned by client:standing:<name>, which a thread read refuses the owner.
	ReadCharacterThread(context.Context, *connect.Request[v1.ReadCharacterThreadRequest]) (*connect.Response[v1.ReadCharacterThreadResponse], error)
	// ReadCharacterThread, then each new entry, until the stream's age (90 s) is up; the client reconnects from next_seq.
	WatchCharacterThread(context.Context, *connect.Request[v1.WatchCharacterThreadRequest], *connect.ServerStream[v1.WatchCharacterThreadResponse]) error
	// docs/adr/0084 amendment A4/A5, owner only: parks the thread. Its SDK session id and transcript are kept, and the
	// owner's next PostToCharacter on that key resumes it with full context. Only a turn in flight is aborted. Closing a
	// parked thread is a no-op; main never closes (thread_not_found).
	CloseCharacterThread(context.Context, *connect.Request[v1.CloseCharacterThreadRequest]) (*connect.Response[v1.CloseCharacterThreadResponse], error)
}

